// The share of seats taken through Berlin's day, hour by hour: the median of the last four weeks'
// weekdays, the median of their weekends, and today so far, for the room picked (or every room the
// Seatfinder estimates). No clicks.

// @constants begin
const KINDS = [
  { kind: 'Weekday', name: 'Weekdays, median', colour: '#8AB8FF', dash: 'solid' },
  { kind: 'Weekend', name: 'Weekends, median', colour: '#B877D9', dash: 'dashed' },
];
const TODAY = { kind: 'Today', name: 'Today', colour: '#FADE2A' };
// @constants end

const theme = context.grafana.theme;
const text = theme.colors.text.primary;
const muted = theme.colors.text.secondary;
const grid = theme.colors.border.weak;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const colOf = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v === null || v === undefined ? null : Number(v));

const hours = Array.from({ length: 24 }, (_, h) => h);
const label = (h) => `${String(h).padStart(2, '0')}:00`;
const kinds = colOf('day_kind');
const hourCol = colOf('hour');
const pct = colOf('pct');
const scope = colOf('scope')[0] ?? '';

const valuesOf = (kind) => {
  const values = new Array(24).fill(null);
  kinds.forEach((k, i) => {
    if (String(k) === kind) values[num(hourCol[i])] = num(pct[i]);
  });
  return values;
};

const series = KINDS.map((k) => ({
  name: k.name,
  type: 'line',
  data: valuesOf(k.kind),
  showSymbol: false,
  lineStyle: { color: k.colour, width: 2, type: k.dash },
  itemStyle: { color: k.colour },
}));
series.push({
  name: TODAY.name,
  type: 'line',
  data: valuesOf(TODAY.kind),
  showSymbol: true,
  symbolSize: 5,
  lineStyle: { color: TODAY.colour, width: 3 },
  itemStyle: { color: TODAY.colour },
  z: 5,
});

return {
  animation: false,
  backgroundColor: 'transparent',
  title: { text: scope, left: 0, top: 0, textStyle: { color: text, fontSize: 12, fontWeight: 'normal' } },
  grid: { left: 8, right: 16, top: 52, bottom: 28, containLabel: true },
  legend: { top: 20, left: 0, textStyle: { color: muted }, itemWidth: 18 },
  tooltip: {
    trigger: 'axis',
    valueFormatter: (v) => (v === null || v === undefined ? '–' : `${Math.round(v)} % taken`),
  },
  xAxis: {
    type: 'category',
    data: hours.map(label),
    boundaryGap: false,
    axisLabel: { color: muted, interval: 2 },
    axisLine: { lineStyle: { color: grid } },
    name: 'Berlin time',
    nameLocation: 'middle',
    nameGap: 24,
    nameTextStyle: { color: muted },
  },
  yAxis: {
    type: 'value',
    min: 0,
    max: 100,
    axisLabel: { color: muted, formatter: (v) => `${v} %` },
    splitLine: { lineStyle: { color: grid } },
  },
  series,
};

